import{_ as d,C as o,o as r,c as n,aj as a,E as s}from"./framework.js";const u=JSON.parse('{"title":"页面设置 | Cms / Site | Documentation","description":"页面设置 in Kooboo: 在实时预览旁维护页面的路由、Meta、本页样式脚本与缓存等，不直接改 HTML 正文（正文在 编辑代码 或 在线编辑）。","frontmatter":{"title":"页面设置 | Cms / Site | Documentation","description":"页面设置 in Kooboo: 在实时预览旁维护页面的路由、Meta、本页样式脚本与缓存等，不直接改 HTML 正文（正文在 编辑代码 或 在线编辑）。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/site/pages-setting.html"}]]},"headers":[],"relativePath":"zh/cms/site/pages-setting.md","filePath":"cms/site/pages-setting.md","lastUpdated":1780283318000}'),i={name:"zh/cms/site/pages-setting.md"};function h(l,t,c,g,p,b){const e=o("DocImage");return r(),n("div",null,[t[0]||(t[0]=a('<h1 id="页面设置" tabindex="-1">页面设置 <a class="header-anchor" href="#页面设置" aria-label="Permalink to &quot;页面设置&quot;">​</a></h1><blockquote><p>从 <a href="./pages.html">页面列表</a> 行内 <strong>设置</strong> 进入<br> 深链（HTML 页面）：<code>/_Admin/page/setting?SiteId={站点GUID}&amp;id={页面Id}</code><br> Layout 页面：<code>/_Admin/page/layout-setting?SiteId=...&amp;id=...&amp;layoutId={LayoutId}</code></p></blockquote><p>在<strong>实时预览</strong>旁维护页面的路由、Meta、本页样式脚本与缓存等，<strong>不直接改 HTML 正文</strong>（正文在 <a href="./pages-edit-code.html">编辑代码</a> 或 <a href="./pages-inline-edit.html">在线编辑</a>）。</p><div class="tip custom-block"><p class="custom-block-title">页面类型</p><table tabindex="0"><thead><tr><th>类型</th><th>能否进入本页</th></tr></thead><tbody><tr><td>HTML 页面、Layout 页面</td><td>是</td></tr><tr><td>富文本页面</td><td>否（列表进入富文本编辑器）</td></tr><tr><td>设计页面（Designer）</td><td>列表进入可视化 <strong>设计</strong>，非本设置布局</td></tr></tbody></table></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li><strong>页面</strong> → 在列表中找到目标行。</li><li>点击 <strong>设置</strong>（齿轮图标）。</li><li>地址栏出现 <code>page/setting</code> 或 <code>page/layout-setting</code>。</li></ol>',6)),s(e,{src:"/cms/site/pages-setting.png",alt:"页面设置：左侧预览与右侧设置面板",width:"1120"}),t[1]||(t[1]=a('<h2 id="界面布局" tabindex="-1">界面布局 <a class="header-anchor" href="#界面布局" aria-label="Permalink to &quot;界面布局&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>左侧主区</td><td>当前页面在站点域名下的<strong>预览</strong>（iframe），随右侧修改刷新</td></tr><tr><td>右上</td><td>页面名称（一般只读，创建后不可改资源名）</td></tr><tr><td>右侧栏</td><td><strong>设置</strong> 折叠面板 + <strong>多语言</strong> 切换（站点启用多语言时）</td></tr><tr><td>底部栏</td><td><strong>返回</strong>、<strong>保存</strong>、<strong>保存并返回</strong></td></tr></tbody></table><p>离开页面前若有未保存修改，会提示确认。</p><h2 id="右侧设置分组" tabindex="-1">右侧设置分组 <a class="header-anchor" href="#右侧设置分组" aria-label="Permalink to &quot;右侧设置分组&quot;">​</a></h2><h3 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>URL</td><td>默认语言的访问路径，须唯一</td></tr><tr><td>多语言 URL</td><td>各语言独立路径（启用多语言时）</td></tr><tr><td>内容标题</td><td>各语言的页面标题（<code>&lt;title&gt;</code> 等会引用）</td></tr><tr><td>发布</td><td>是否对外发布该页</td></tr></tbody></table><p>修改 URL 后请用左侧预览或列表 <strong>预览</strong> 列确认路径可访问。</p><h3 id="html-meta" tabindex="-1">HTML Meta <a class="header-anchor" href="#html-meta" aria-label="Permalink to &quot;HTML Meta&quot;">​</a></h3><p>管理 <code>&lt;head&gt;</code> 中的 meta、link 等（如 description、keywords、Open Graph）。增删改后保存生效。</p><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><p>配置页面 <strong>URL 参数</strong> 及与模板/绑定的关系，供带查询串或动态段的页面使用。</p><h3 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h3><p>为本页<strong>单独引用</strong>站点 Style 资源，可排序、插入、移除。与 Layout / 全局样式叠加关系以实际渲染为准。</p><p>若站点开启 UnoCSS，可在此页勾选 <strong>禁用 UnoCSS</strong>。</p><h3 id="脚本" tabindex="-1">脚本 <a class="header-anchor" href="#脚本" aria-label="Permalink to &quot;脚本&quot;">​</a></h3><p>为本页引用站点 Script 资源，操作方式同样式分组。</p><h3 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>启用缓存</td><td>是否缓存本页输出</td></tr><tr><td>按设备 / 语言 / 版本</td><td>缓存键维度（有提示文案）</td></tr><tr><td>缓存分钟数</td><td>过期时间</td></tr><tr><td>Query 键</td><td>参与缓存区分的查询参数</td></tr></tbody></table><p>详情页、个性化页通常关闭或缩短缓存。</p><h2 id="layout-页面差异" tabindex="-1">Layout 页面差异 <a class="header-anchor" href="#layout-页面差异" aria-label="Permalink to &quot;Layout 页面差异&quot;">​</a></h2><p>绑定 Layout 的页面使用 <code>layout-setting</code> 路由，右侧除上述分组外，可能包含 <strong>设计 / 设置</strong> 等 Tab（在 Layout 占位与页面属性间切换）。占位区 HTML 仍在 <strong>编辑代码</strong>（<code>layout-edit</code>）中维护。</p><h2 id="与另外两种编辑方式的分工" tabindex="-1">与另外两种编辑方式的分工 <a class="header-anchor" href="#与另外两种编辑方式的分工" aria-label="Permalink to &quot;与另外两种编辑方式的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>建议</th></tr></thead><tbody><tr><td>改 URL、标题、Meta、发布、缓存</td><td><strong>本页（设置）</strong></td></tr><tr><td>改 HTML 结构、<code>&lt;layout&gt;</code> / <code>&lt;placeholder&gt;</code>、<code>&lt;view&gt;</code></td><td><a href="./pages-edit-code.html">编辑代码</a></td></tr><tr><td>改可见文案、图片、链接、简单样式</td><td><a href="./pages-inline-edit.html">在线编辑</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./pages.html">页面列表</a></td><td>入口与列表操作</td></tr><tr><td><a href="./pages-edit-code.html">编辑代码</a></td><td>Monaco 编辑 body</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/page/">模板引擎 · Page</a></td><td>占位与 Layout 写法</td></tr><tr><td><a href="/kb-docs/zh/api/page/">k.page</a></td><td>运行时改当前页 Meta（非仓库设置）</td></tr></tbody></table>',25))])}const _=d(i,[["render",h]]);export{u as __pageData,_ as default};
